
(()=>{const root=document.getElementById('chance2'),$=s=>root.querySelector(s);const data=window.CHANCE2_CATALOG; const pricing=window.CHANCE2_PRICING;let page=1,bag=[];const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);const price=p=>{const shipping=pricing.supplierShippingBySku[p.sku]??pricing.defaultSupplierShipping;if(p.supplierPrice==null||shipping==null)return null;return Math.round(((p.supplierPrice+shipping)*pricing.multiplier+Number.EPSILON)*100)/100;};const category=p=> /chair|stool|sofa|seating|recliner/i.test(p.name)?'Chairs & seating':/desk|table|workstation/i.test(p.name)?'Desks & tables':/cabinet|shelv|bookcase|locker|storage/i.test(p.name)?'Storage & shelving':'Accessories';const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){let list=data.products.filter(p=>(p.name+' '+p.sku).toLowerCase().includes($('#search').value.toLowerCase())&&($('#category').value==='All furniture'||category(p)===$('#category').value));let sort=$('#sort').value;if(sort==='low')list.sort((a,b)=>(price(a)??Infinity)-(price(b)??Infinity));if(sort==='high')list.sort((a,b)=>(price(b)??-1)-(price(a)??-1));if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));if(sort==='featured')list.sort((a,b)=>Number(category(a)==='Accessories')-Number(category(b)==='Accessories'));const pages=Math.max(1,Math.ceil(list.length/12));page=Math.min(page,pages);$('#count').textContent=list.length.toLocaleString()+' products';$('#products').innerHTML=list.slice((page-1)*12,page*12).map(p=>`<article class="product"><img loading="lazy" src="${esc(p.image)}" alt="${esc(p.name)}"><small>${esc(p.sku)}</small><h3>${esc(p.name)}</h3><div class="price">${price(p)==null?'Request a quote':money(price(p))}</div><button data-sku="${esc(p.url)}" ${price(p)==null?'disabled':''}>Add to bag +</button></article>`).join('')||'<p class="empty">No matching furniture. Try another search.</p>';$('#page').textContent=`Page ${page} of ${pages}`;$('#prev').disabled=page===1;$('#next').disabled=page===pages;}
['search','category','sort'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',()=>{page=1;render()}));$('#prev').onclick=()=>{page--;render()};$('#next').onclick=()=>{page++;render()};$('#products').onclick=e=>{let b=e.target.closest('button[data-sku]');if(b){bag.push(data.products.find(p=>p.url===b.dataset.sku));$('#bag').textContent=`Your bag (${bag.length})`;b.textContent='Added ✓';}};$('#bag').onclick=()=>{showCart();$('#cart').showModal()};function showCart(){$('#cartitems').innerHTML=bag.map((p,i)=>`<div class="cartrow"><span>${esc(p.name)}</span><strong>${money(price(p))}</strong><button data-remove="${i}" aria-label="Remove ${esc(p.name)}">×</button></div>`).join('')||'<p>Your bag is empty.</p>';$('#total').textContent='Subtotal: '+money(bag.reduce((s,p)=>s+price(p),0));}$('#cartitems').onclick=e=>{let b=e.target.closest('[data-remove]');if(b){bag.splice(+b.dataset.remove,1);$('#bag').textContent=`Your bag (${bag.length})`;showCart()}};$('#close').onclick=()=>$('#cart').close();render();})();
